import { MakeLogicType, afterMount, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { getUsage } from '../../api'
import type { KnowledgeUsage } from '../../api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface businessKnowledgeUsageLogicValues {
    ingestionLimited: boolean
    retrievalLimited: boolean
    usage: KnowledgeUsage | null
    usageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface businessKnowledgeUsageLogicActions {
    loadUsage: () => any
    loadUsageFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadUsageSuccess: (
        usage: KnowledgeUsage | null,
        payload?: any
    ) => {
        usage: KnowledgeUsage | null
        payload?: any
    }
}

export type businessKnowledgeUsageLogicType = MakeLogicType<
    businessKnowledgeUsageLogicValues,
    businessKnowledgeUsageLogicActions
>

export const businessKnowledgeUsageLogic = kea<businessKnowledgeUsageLogicType>([
    path(['products', 'business_knowledge', 'frontend', 'components', 'UsageMeter', 'businessKnowledgeUsageLogic']),
    loaders({
        usage: [
            null as KnowledgeUsage | null,
            {
                loadUsage: async () => await getUsage(),
            },
        ],
    }),
    selectors({
        ingestionLimited: [(s) => [s.usage], (usage): boolean => !!usage?.chunks.limited],
        retrievalLimited: [(s) => [s.usage], (usage): boolean => !!usage?.queries.limited],
    }),
    afterMount(({ actions }) => {
        actions.loadUsage()
    }),
])
